public class Main {
    public static void main(String[] args) {
        int rows = 4;
        for (int i = 1; i <= rows; i++) {
            StringBuilder line = new StringBuilder();
            for (int s = 0; s < rows - i; s++) {
                line.append(' ');
            }
            for (int k = 0; k < 2 * i - 1; k++) {
                line.append('*');
            }
            System.out.println(line);
        }
    }
}
